import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.NpvCl_7q.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/architecture.md","filePath":"contributing/architecture.md","lastUpdated":1792608207000}'),n={name:"contributing/architecture.md"};function i(d,e,r,c,l,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>This page is a map for contributors. <code>MASON_CONTEXT.md</code> at the repo root goes deeper on each area and lists the invariants that have bitten people before.</p><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> TypeScript plugin (packages/nativescript-masonkit)</span></span>
<span class="line"><span>   elements, CSS properties, style buffer writes</span></span>
<span class="line"><span>        |  shared style buffer + dirty mask</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span> Native view layer</span></span>
<span class="line"><span>   Android: Kotlin (src-native/mason-android)</span></span>
<span class="line"><span>   iOS:     Swift  (src-native/mason-ios)</span></span>
<span class="line"><span>   Windows: C++/WinRT (src-native/windows)</span></span>
<span class="line"><span>        |  JNI / C ABI</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span> Rust bindings (crates/mason-android, mason-ios, mason-windows, mason-c)</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span> mason-core (crates/mason-core), built on taffy</span></span></code></pre></div><h3 id="mason-core" tabindex="-1">mason-core <a class="header-anchor" href="#mason-core" aria-label="Permalink to &quot;mason-core&quot;">​</a></h3><p>The layout engine. It owns the node tree and style storage and runs flexbox, grid, block, inline flow and floats on top of <a href="https://github.com/DioxusLabs/taffy" target="_blank" rel="noreferrer">taffy</a>. The workspace pins a fork of taffy (<code>Cargo.toml</code>, <code>[workspace.dependencies]</code>) that carries flexbox and out-of-flow sizing fixes not yet upstream.</p><p>For text, Rust only sizes boxes. The platform breaks and draws lines, and reports sizes back through measure callbacks. That keeps text rendering native (CoreText on iOS, Android&#39;s text stack, DirectWrite on Windows).</p><h3 id="bindings" tabindex="-1">Bindings <a class="header-anchor" href="#bindings" aria-label="Permalink to &quot;Bindings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Crate</th><th>Output</th><th>Used by</th></tr></thead><tbody><tr><td><code>mason-android</code></td><td><code>libmasonnative.so</code> (cdylib, JNI)</td><td>The Kotlin library, built by Gradle</td></tr><tr><td><code>mason-c</code></td><td>C ABI (<code>mason_native.h</code>)</td><td><code>mason-ios</code> and <code>mason-windows</code> re-export it</td></tr><tr><td><code>mason-ios</code></td><td><code>libmasonnative.a</code> (staticlib)</td><td>The Swift framework, built by an Xcode build phase</td></tr><tr><td><code>mason-windows</code></td><td><code>masonnative.lib</code> (staticlib)</td><td>The C++/WinRT component</td></tr></tbody></table><p>C headers are generated with cbindgen (<code>tools/scripts/build-headers.sh</code>, and on every iOS build by <code>pre-build.sh</code>).</p><h3 id="native-view-layer" tabindex="-1">Native view layer <a class="header-anchor" href="#native-view-layer" aria-label="Permalink to &quot;Native view layer&quot;">​</a></h3><p>Each platform has the same set of elements: a container view, scroll view, text, image, button, input, text area, list, list item and line break. They own a Mason node, apply computed layout to their frames, draw backgrounds, borders, shadows, masks and filters, and handle touch, focus and accessibility.</p><p>Android&#39;s text view is a <code>ViewGroup</code> that draws its own text, so inline boxes (inline-blocks, buttons, images and inputs inside text) can be real child views. iOS&#39;s <code>MasonText</code> does the same with subviews, and Windows keeps them as live XAML children.</p><h3 id="typescript-plugin" tabindex="-1">TypeScript plugin <a class="header-anchor" href="#typescript-plugin" aria-label="Permalink to &quot;TypeScript plugin&quot;">​</a></h3><ul><li><code>view/</code>, <code>text/</code>, <code>scroll/</code>, <code>img/</code>, <code>button/</code>, <code>input/</code>, <code>textarea/</code>, <code>br/</code>, <code>list/</code>, <code>li/</code>, <code>text-node/</code>: the element classes, split into <code>common.ts</code> plus <code>index.{ios,android,windows}.ts</code>.</li><li><code>web.ts</code>: the HTML-shaped elements (<code>div</code>, <code>section</code>, <code>p</code>, <code>h1</code>-<code>h6</code>, <code>span</code>, <code>a</code>, <code>ul</code>, <code>details</code>, ...). Block containers extend <code>Scroll</code>, so any of them can scroll when <code>overflow</code> says so; phrasing elements extend <code>Text</code>.</li><li><code>style.ts</code>: the <code>Style</code> class that writes the shared style buffer.</li><li><code>properties.ts</code>: CSS property registration on NativeScript&#39;s <code>Style</code>, so stylesheets cascade onto Mason elements.</li><li><code>elements.ts</code>: the element registry (<code>getMasonKitElements()</code>).</li><li><code>css-*.ts</code>, <code>box-shadow.ts</code>, <code>gradient-stops.ts</code>, <code>units.ts</code>: value parsers (colors, math functions, filters, transforms, keyframes, units).</li><li>Windows-only modules use the platform suffix too: <code>mask.windows.ts</code> (mask, clip-path and background specs for Direct2D), <code>panel-helpers.windows.ts</code>, <code>svg-path.windows.ts</code> and <code>inner-html.windows.ts</code>. Import them without the suffix. Shared code (<code>common.ts</code>, <code>style.ts</code>, <code>web.ts</code>) imports <code>./mask</code> and <code>./panel-helpers</code>, so those two also have a base <code>mask.ts</code> / <code>panel-helpers.ts</code> that iOS and Android resolve to; it only declares the shared types and stubs that run behind <code>__WINDOWS__</code>. <code>svg-path.d.ts</code> types the Windows-only <code>svg-path</code> module.</li></ul><h2 id="the-style-buffer" tabindex="-1">The style buffer <a class="header-anchor" href="#the-style-buffer" aria-label="Permalink to &quot;The style buffer&quot;">​</a></h2><p>Every Mason node has a byte buffer holding its style. JavaScript and the native layer see the <strong>same memory</strong>: on Android an <code>ArrayBuffer</code> over a direct <code>ByteBuffer</code>, on iOS <code>interop.bufferFromData</code> over <code>NSMutableData</code>, on Windows the runtime&#39;s view of a WinRT <code>IBuffer</code>. A new node starts on a shared default buffer and takes its own copy on first write.</p><p>The byte offsets (<code>StyleKeys</code>) and the bits of the 128-bit dirty mask (<code>StateKeys</code>) are generated for every language from one file, <code>tools/scripts/style-keys/style-keys.schema</code>. <code>npm run gen:style-keys</code> rewrites the marked blocks in:</p><ul><li><code>crates/mason-core/src/style/mod.rs</code> and <code>crates/mason-core/src/style/arena.rs</code></li><li><code>src-native/mason-android/.../masonkit/Style.kt</code></li><li><code>src-native/mason-ios/Mason/Mason/MasonStyle.swift</code></li><li><code>packages/nativescript-masonkit/style.ts</code></li><li><code>src-native/windows/Mason/StyleKeys.h</code> (the whole file)</li></ul><p><code>npm run test:keys</code> fails in CI when any of them is stale or was edited by hand.</p><h2 id="from-a-style-write-to-a-layout" tabindex="-1">From a style write to a layout <a class="header-anchor" href="#from-a-style-write-to-a-layout" aria-label="Permalink to &quot;From a style write to a layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>style.width = &#39;50%&#39;                       (style.ts setter)</span></span>
<span class="line"><span>  -&gt; write WIDTH_TYPE / WIDTH_VALUE bytes, commitState(StateKeys.SIZE)</span></span>
<span class="line"><span>  -&gt; microtask: flushStyleSyncs()</span></span>
<span class="line"><span>  -&gt; syncStyleParts(d0, d1, d2, d3)       (dirty mask as four int32 words)</span></span>
<span class="line"><span>       Android: Element.syncStyleParts    iOS: mason_syncStyleParts</span></span>
<span class="line"><span>  -&gt; Style.setStateFromHalves(low, high)</span></span>
<span class="line"><span>  -&gt; native reads the changed fields, invalidates layout or repaints</span></span></code></pre></div><p>Writes made in the same turn are batched into one sync per style. The JS setters bypass the typed native property setters entirely, so behaviour that must run on a style change belongs on the sync path, not in a Kotlin or Swift property setter.</p><h2 id="adding-a-style-field" tabindex="-1">Adding a style field <a class="header-anchor" href="#adding-a-style-field" aria-label="Permalink to &quot;Adding a style field&quot;">​</a></h2><ol><li>Append the field to <code>[style]</code> in <code>style-keys.schema</code> (and a bit to <code>[state]</code> if it needs its own dirty flag). Never move or resize an existing field; offsets are shared between the Rust core and the platforms.</li><li>Run <code>npm run gen:style-keys</code>.</li><li>Write the setter and getter in <code>style.ts</code>: write the buffer, then <code>commitState</code>.</li><li>Register the CSS property in <code>properties.ts</code>.</li><li>Read the bytes natively (Rust if it affects layout, the platform layers if it affects drawing).</li><li>Add a Node test that sets the property and reads the bytes back.</li></ol><div class="warning custom-block"><p class="custom-block-title">Reserved but unwritable</p><p>The recurring bug shape: an offset exists and the natives read it, but nothing in JS ever writes it, so the property looks supported and silently does nothing. Step 6 is what catches it.</p></div><h2 id="css-and-plain-nativescript-views" tabindex="-1">CSS and plain NativeScript views <a class="header-anchor" href="#css-and-plain-nativescript-views" aria-label="Permalink to &quot;CSS and plain NativeScript views&quot;">​</a></h2><p>NativeScript&#39;s own CSS engine does the stylesheet work (selectors, classes, <code>@media</code>, <code>@keyframes</code>, <code>var()</code>, specificity). MasonKit registers its properties on core&#39;s <code>Style</code>, so <code>.css</code> files cascade onto <code>&lt;div&gt;</code>, <code>&lt;p&gt;</code> and friends.</p><p>Some CSS names (<code>margin</code>, <code>padding</code>, <code>background</code>, <code>border-radius</code>, <code>flex</code>, <code>transform</code>, ...) are already registered by core. Registering them again would replace core&#39;s handling for every view in the app. Two helpers in <code>properties.ts</code> prevent that:</p><ul><li><code>registerAlongsideCore(property)</code> keeps core&#39;s descriptor and picks the Mason or core path per view at assignment time, based on <code>isMasonView</code>.</li><li><code>overrideForMasonViews(property, ...)</code> is for core properties MasonKit narrows; it falls back to core&#39;s original handlers for plain views.</li></ul><p>Any new property that collides with a core CSS name must go through one of them; <code>properties.spec.ts</code> fails otherwise.</p><p>A plain NativeScript view inside a Mason container becomes a Mason leaf node and takes part in flex or grid as one box. <code>foreign-layout.ts</code> mirrors its layout properties (size, margins, flex, alignment, position, grid placement) into that leaf. A Mason view inside a plain NativeScript layout acts as its own layout root.</p><h2 id="the-element-registry" tabindex="-1">The element registry <a class="header-anchor" href="#the-element-registry" aria-label="Permalink to &quot;The element registry&quot;">​</a></h2><p><code>elements.ts</code> exports <code>getMasonKitElements()</code>, the single list of every tag MasonKit backs: the <code>/web</code> HTML elements (tag read from each class&#39;s <code>@CSSType</code> decorator) and MasonKit&#39;s own widgets (<code>View</code>, <code>Text</code>, <code>Scroll</code>, <code>Img</code>, <code>Button</code>, <code>Input</code>, <code>TextArea</code>, <code>Br</code>, <code>Ul</code>, <code>Ol</code>, <code>Li</code>). Each entry says whether the element is a container that needs child-aware wiring.</p><p>The Angular, Vue and Svelte entry points build their <code>registerElement</code> loops from it, and <code>npm run gen:jsx-types</code> generates the JSX intrinsic typings for the React demo from the same sources. Adding a tag to <code>web.ts</code> reaches every framework at once; <code>elements.spec.ts</code> guards the list.</p><p>UA default styles for tags (heading sizes, paragraph and list margins) are applied through <code>applyUaCss()</code> in <code>web.ts</code>, which writes them at the stylesheet tier rather than as local values, so app CSS such as <code>ul { margin: 0 }</code> can override them.</p>`,36)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
